import React from "react";
import { Box, Typography, Stack, Paper } from "@mui/material";
import cafeImg from "../../assets/cafeInside.png";
import { useTheme } from "@mui/material/styles";

function Home() {
  const theme = useTheme();
  return (
    <Box sx={{mx: "auto"}}>
      {/* pink stripe */}
      <Box sx={{ width: "100%", my: 0, height: 50, bgcolor: theme.palette.primary.blushPink  }}/>
      {/* Main hero photo */}
      <Box component="img" src={cafeImg} alt=" Cafe inner image" sx={{width: "100%", my: 0, height: "auto", objectFit: "cover"}} />
      {/* stone stripe Contact details*/} 
      <Box sx={{width: "100%", my: 0, height: "auto", bgcolor: theme.palette.primary.stone }}>
        <Stack spacing={3} sx={{ mt: 4 }}>
          <Paper elevation={ 3 } sx={{ p: 3, bgcolor}}>

          </Paper>
        </Stack>
      </Box>
      {/* choco stripe */}
      <Box sx={{ width: "100%", my: 0, height: 100, bgcolor: theme.palette.primary.choco  }}/>

    </Box>
  );
}

export default Home;
